def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    evaluating: set[str] = set()

    def failed(value: object) -> bool:
        return isinstance(value, str)

    def trunc_div(left: int, right: int) -> int | str:
        if right == 0:
            return "#DIV/0!"
        negative = (left < 0) != (right < 0)
        quotient = abs(left) // abs(right)
        return -quotient if negative else quotient

    def coordinates(name: str) -> tuple[int, int]:
        return ord(name[0]), int(name[1:])

    def eval_cell(name: str) -> int | str:
        if name in memo:
            return memo[name]
        if name not in cells:
            return 0
        if name in evaluating:
            return "#CYCLE!"
        evaluating.add(name)
        text = cells[name].strip()
        if text.startswith("="):
            value = eval_node(parse(text[1:]))
        else:
            value = int(text)
        memo[name] = value
        evaluating.remove(name)
        return value

    def eval_node(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "cell":
            return eval_cell(node[1])
        if kind == "neg":
            value = eval_node(node[1])
            if failed(value):
                return value
            return -value
        if kind == "bin":
            op, left, right = node[1], node[2], node[3]
            lval = eval_node(left)
            if failed(lval):
                return lval
            rval = eval_node(right)
            if failed(rval):
                return rval
            if op == "+":
                return lval + rval
            if op == "-":
                return lval - rval
            if op == "*":
                return lval * rval
            return trunc_div(lval, rval)
        if kind in ("SUM", "MIN", "MAX"):
            return eval_call(kind, node[1])
        if kind == "IF":
            return eval_if(*node[1:])
        raise AssertionError(kind)

    def eval_range(start: str, end: str):
        c1, r1 = coordinates(start)
        c2, r2 = coordinates(end)
        values = []
        for row in range(min(r1, r2), max(r1, r2) + 1):
            for col in range(min(c1, c2), max(c1, c2) + 1):
                name = chr(col) + str(row)
                if name not in cells:
                    continue
                value = eval_cell(name)
                if failed(value):
                    return value
                values.append(value)
        return values

    def eval_call(kind: str, args):
        values = []
        for arg in args:
            if arg[0] == "range":
                got = eval_range(arg[1], arg[2])
                if failed(got):
                    return got
                values.extend(got)
            else:
                value = eval_node(arg)
                if failed(value):
                    return value
                values.append(value)
        if kind == "SUM":
            return sum(values)
        if not values:
            return 0
        if kind == "MIN":
            return min(values)
        return max(values)

    def eval_if(left, op, right, then_branch, else_branch):
        lval = eval_node(left)
        if failed(lval):
            return lval
        rval = eval_node(right)
        if failed(rval):
            return rval
        if op == "=":
            cond = lval == rval
        elif op == "<>":
            cond = lval != rval
        elif op == "<":
            cond = lval < rval
        elif op == "<=":
            cond = lval <= rval
        elif op == ">":
            cond = lval > rval
        else:
            cond = lval >= rval
        return eval_node(then_branch if cond else else_branch)

    class Parser:
        def __init__(self, text: str):
            self.s = text
            self.n = len(text)
            self.i = 0

        def skip(self) -> None:
            while self.i < self.n and self.s[self.i] == " ":
                self.i += 1

        def parse(self):
            return self.expr()

        def expr(self):
            node = self.term()
            while True:
                self.skip()
                if self.i < self.n and self.s[self.i] in "+-":
                    op = self.s[self.i]
                    self.i += 1
                    node = ("bin", op, node, self.term())
                else:
                    return node

        def term(self):
            node = self.unary()
            while True:
                self.skip()
                if self.i < self.n and self.s[self.i] in "*/":
                    op = self.s[self.i]
                    self.i += 1
                    node = ("bin", op, node, self.unary())
                else:
                    return node

        def unary(self):
            self.skip()
            if self.i < self.n and self.s[self.i] == "-":
                self.i += 1
                return ("neg", self.unary())
            return self.atom()

        def atom(self):
            self.skip()
            char = self.s[self.i]
            if char == "(":
                self.i += 1
                node = self.expr()
                self.skip()
                self.i += 1
                return node
            if char.isdigit():
                start = self.i
                while self.i < self.n and self.s[self.i].isdigit():
                    self.i += 1
                return ("num", int(self.s[start:self.i]))
            cell = self.try_cell()
            if cell is not None:
                return ("cell", cell)
            start = self.i
            while self.i < self.n and "A" <= self.s[self.i] <= "Z":
                self.i += 1
            name = self.s[start:self.i]
            self.skip()
            self.i += 1
            if name == "IF":
                return self.if_call()
            return (name, self.arguments())

        def try_cell(self):
            i = self.i
            if i >= self.n or not ("A" <= self.s[i] <= "Z"):
                return None
            j = i + 1
            if j >= self.n or not self.s[j].isdigit():
                return None
            k = j
            while k < self.n and self.s[k].isdigit():
                k += 1
            number = self.s[j:k]
            if number[0] == "0":
                return None
            row = int(number)
            if row < 1 or row > 99:
                return None
            self.i = k
            return self.s[i] + number

        def arguments(self):
            args = [self.argument()]
            while True:
                self.skip()
                if self.s[self.i] == ",":
                    self.i += 1
                    args.append(self.argument())
                else:
                    self.i += 1
                    return args

        def argument(self):
            save = self.i
            self.skip()
            cell = self.try_cell()
            if cell is not None:
                self.skip()
                if self.i < self.n and self.s[self.i] == ":":
                    self.i += 1
                    self.skip()
                    other = self.try_cell()
                    return ("range", cell, other)
            self.i = save
            return self.expr()

        def if_call(self):
            left = self.expr()
            op = self.comparison()
            right = self.expr()
            self.comma()
            then_branch = self.expr()
            self.comma()
            else_branch = self.expr()
            self.skip()
            self.i += 1
            return ("IF", left, op, right, then_branch, else_branch)

        def comparison(self) -> str:
            self.skip()
            two = self.s[self.i:self.i + 2]
            if two in ("<>", "<=", ">="):
                self.i += 2
                return two
            op = self.s[self.i]
            self.i += 1
            return op

        def comma(self) -> None:
            self.skip()
            self.i += 1

    def parse(text: str):
        return Parser(text).parse()

    return {name: eval_cell(name) for name in cells}
